import{_ as t,o,c as a,a2 as s}from"./chunks/framework.1C62pOns.js";const m=JSON.parse('{"title":"Integrations","description":"","frontmatter":{},"headers":[],"relativePath":"en/interface/integracoes.md","filePath":"en/interface/integracoes.md","lastUpdated":1791311821000}'),n={name:"en/interface/integracoes.md"};function r(i,e,h,d,l,c){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="integrations" tabindex="-1">Integrations <a class="header-anchor" href="#integrations" aria-label="Permalink to &quot;Integrations&quot;">​</a></h1><p>They take an agent or team to where people already talk — WhatsApp, Teams, Telegram, e-mail — instead of asking them to come into the platform.</p><p>Since version 1.0.26.7 the platform no longer talks to each channel on its own: the WhatsApp (Evolution API) and Microsoft Teams integrations were removed. The channel is handled by <strong>N8N</strong>, which already has a ready-made node for each of them. The platform takes care of what is its own: the agent, the team, the workflow.</p><h2 id="from-the-channel-to-the-platform" tabindex="-1">From the channel to the platform <a class="header-anchor" href="#from-the-channel-to-the-platform" aria-label="Permalink to &quot;From the channel to the platform&quot;">​</a></h2><p>The path is always the same:</p><ol><li>an N8N flow receives the message from the channel (the WhatsApp trigger, the Teams trigger…);</li><li>an <strong>HTTP Request</strong> node calls the platform workflow that talks to the agent;</li><li>the workflow&#39;s answer goes back to the channel through N8N&#39;s own send node.</li></ol><p>The call is the workflow trigger by API:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/workflow/&lt;id&gt;/run</span></span>
<span class="line"><span>Authorization: Basic &lt;workflow API token&gt;</span></span>
<span class="line"><span>X-Impersonate-User: &lt;platform user&gt;   (optional)</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{ &quot;message&quot;: &quot;received text&quot;, &quot;sender&quot;: &quot;...&quot; }</span></span></code></pre></div><p>The body becomes the execution context, and the response carries the workflow&#39;s result right away — there is no need to poll for it. The token is the one on the <a href="/pro-agent-hub-installer/en/interface/administracao">Administration</a> screen, and <code>X-Impersonate-User</code> decides on whose behalf the workflow runs: without it, it runs as the service user.</p><div class="tip custom-block"><p class="custom-block-title">Who wrote the message</p><p>What comes from the channel — name, number, e-mail — is written by whoever sent the message. Pass those fields to the agent as data, never as instructions, and do not use them to decide permissions.</p></div><h2 id="from-the-platform-to-n8n" tabindex="-1">From the platform to N8N <a class="header-anchor" href="#from-the-platform-to-n8n" aria-label="Permalink to &quot;From the platform to N8N&quot;">​</a></h2><blockquote><p>Registered under <strong>Settings → N8N tab</strong>, masters only.</p></blockquote><p>An N8N integration holds the <strong>instance address</strong> (e.g. <code>https://n8n.company.com</code>, or <code>https://company.com/n8n</code> if N8N runs under a sub-path; never with <code>/webhook/</code>), the webhook <strong>authentication</strong> and the default <strong>timeout</strong> for calls.</p><p><strong>Authentication.</strong> The N8N Webhook node offers <em>Header Auth</em>, <em>Basic Auth</em>, <em>JWT Auth</em> or none. All of them fit the header/value pair of the record:</p><table tabindex="0"><thead><tr><th>On the Webhook node</th><th>Header</th><th>Value</th></tr></thead><tbody><tr><td>Header Auth</td><td>the credential&#39;s <em>Name</em></td><td>the credential&#39;s <em>Value</em></td></tr><tr><td>Basic Auth</td><td><code>Authorization</code></td><td><code>Basic </code> + base64 of <code>user:password</code></td></tr><tr><td>JWT Auth</td><td><code>Authorization</code></td><td><code>Bearer </code> + the token</td></tr></tbody></table><p>The secret never comes back to the screen: when editing, leave the field blank to keep the current one, or tick <em>Remove the current secret</em>. Nor is it stored in the workflow — the flow keeps only the integration number and the webhook path, which is why whoever builds the workflow cannot send the call somewhere else.</p><p><strong>Advanced</strong> holds the <code>webhook</code> and <code>webhook-test</code> prefixes. Change them only if the N8N instance replaced them through <code>N8N_ENDPOINT_WEBHOOK</code> and <code>N8N_ENDPOINT_WEBHOOK_TEST</code>.</p><p>In a high-code workflow (or a Script node), the call is:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">response </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> call_n8n(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;order-approved&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;order&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;customer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ACME&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><ul><li>the first argument is the integration number (shown in the tab&#39;s list);</li><li>the second is the <em>Path</em> of the Webhook node; with path parameters, give the values (the Path <code>order/:id</code> becomes <code>&quot;order/123&quot;</code>);</li><li>the third is the data: sent as JSON in the body (in N8N, <code>$json.body</code>); with <code>GET</code> and <code>HEAD</code> it becomes URL parameters (<code>$json.query</code>). N8N caps the body at 16 MB.</li></ul><p>The method is the node&#39;s <em>HTTP Method</em> (<code>method=&quot;GET&quot;</code>, for instance; the default is <code>POST</code>). The response depends on the Webhook node&#39;s <em>Respond</em>:</p><table tabindex="0"><thead><tr><th>Respond</th><th>What <code>call_n8n</code> returns</th></tr></thead><tbody><tr><td>Immediately</td><td>the message that the flow has started — it carries on by itself</td></tr><tr><td>When Last Node Finishes</td><td>the output of the last node</td></tr><tr><td>Using &#39;Respond to Webhook&#39; Node</td><td>whatever that node defines</td></tr></tbody></table><p>JSON becomes a dictionary, text stays text and a file (a PDF, say) becomes bytes. The <strong>production</strong> URL only exists while the flow is published in N8N; the <strong>test</strong> one (<code>test_mode=True</code>) only answers while the editor is in <em>Listen for test event</em>, for 120 seconds. An unregistered webhook answers 404, and the error message says so. On N8N Cloud, a flow that does not answer within 100 seconds fails.</p><p>A failure — disabled integration, network, an error response from N8N — raises <code>N8nCallError</code>, with <code>status</code> and <code>body</code> when N8N answered. The full reference is under <a href="/pro-agent-hub-installer/en/funcoes/workflow_highcode">Functions</a>.</p><h3 id="in-a-low-code-workflow" tabindex="-1">In a low-code workflow <a class="header-anchor" href="#in-a-low-code-workflow" aria-label="Permalink to &quot;In a low-code workflow&quot;">​</a></h3><p>The <strong>N8N</strong> node (<em>Integrations</em> group of the palette) makes the same call with no code: pick the integration, give the webhook path (accepts <code>{{variable}}</code>, as in <code>order/{{order_id}}</code>), the method and the data — a variable, a <code>{{node.field}}</code> reference or JSON with variables. The response goes to the output variable (<code>n8n_result</code>). The node has two outputs, <strong>OK</strong> and <strong>ERROR</strong>, like the Planner node: a failure goes out through ERROR when it is connected, and the reason is in <code>{{node_name.n8nError}}</code>. <em>On failure</em> chooses between carrying on, stopping that path or failing the workflow.</p><p>When you export the settings, the N8N integrations go along, with the secret encrypted like the other passwords.</p>`,27)])])}const u=t(n,[["render",r]]);export{m as __pageData,u as default};
